/* isry.itgcm.casemng.caseunity.CaseAftfctMapper.deleteCaseAftfctPlanDetail(사후계획상세삭제) */
UPDATE SEC200 T1  /* 사후계획 */
   SET T1.DEL_YN = #{DEL_YN}
 WHERE T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
   AND T1.AFTFCT_PLAN_NO = #{AFTFCT_PLAN_NO}    -- 사후계획번호(AP)

/* isry.itgcm.casemng.caseunity.CaseAftfctMapper.deleteCaseAftfctMngDetail(사후관리상세삭제) */
UPDATE SEC300 T1  /* 사후관리 */
   SET T1.DEL_YN         = 'Y'
 WHERE T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
   AND T1.AFTFCT_MNG_NO  = #{AFTFCT_MNG_NO}  -- 사후관리번호(AP)

