DELETE /* isry.itgcm.casemng.caseunity.CaseAftfctMapper.deleteCaseAftfctTrmnDetail(사후종결상세삭제) */
  FROM SEC320 T1  /* 사후종결 */
 WHERE T1.AFTFCT_TRMN_NO = #{AFTFCT_TRMN_NO} 
   AND T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

DELETE /* isry.itgcm.casemng.caseunity.CaseAftfctMapper.deleteCaseReasseDetail(재사정상세삭제) */
  FROM SEC110 T1  /* 재사정 */
 WHERE T1.REASSE_NO      = #{REASSE_NO}
   AND T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

