/* isry.itgcm.casemng.caseunity.CaseAftfctMapper.deleteCaseAftfctPicDetail(사후관리담당자상세삭제) */
UPDATE SEC310 T1  /* 사후관리담당자 */
   SET T1.DEL_YN         = 'Y'
 WHERE T1.AFTFCT_MNG_NO  = #{AFTFCT_MNG_NO}
   AND T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
   AND T1.PIC_NO         = #{PIC_NO}

mapper.select:
SELECT /* isry.itgcm.casemng.caseunity.CaseAftfctMapper.selectCaseReasseSrngPicList(재사정심사자목록조회) */ T1.CASE_MNG_NO AS CASE_MNG_NO -- 사례관리번호 , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO -- 사례관리차수 , T1.SRNG_PIC_NO AS SRNG_PIC_NO -- 심사담당자번호 , T1.SRNG_PIC_NO AS SRNG_PIC_NO_ORD -- 심사담당자번호(ORD) , C##RG.DEC_B64(T2.FLNM_ENCPT) AS SRNG_PIC_NM_ENCPT -- 심사담당자명 , T1.PIC_INST_NO AS PIC_INST_NO -- 담당자기관번호 , T3.INST_NM AS PIC_INST_NM -- 담당자기관명 , T1.AFTFCT_TRMN_SRNG_TKCG_YN AS AFTFCT_TRMN_SRNG_TKCG_YN -- 사후종결심사담당여부 , T1.REASSE_SRNG_TKCG_YN AS REASSE_SRNG_TKCG_YN -- 재사정심사담당여부 , T1.FRST_RGTR_ID AS FRST_RGTR_ID -- 최초등록자아이디 , T1.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시 , T1.LAST_MDFR_ID AS LAST_MDFR_ID -- 최종수정자아이디 , T1.LAST_MDFCN_DT AS LAST_MDFCN_DT -- 최종수정일시 FROM SEC130 T1 /* 재사정심사자 */ , SCA100 T2 /* 종사자 */ , SAA000 T3 /* 통합기관 */ WHERE 1 = 1 AND T1.SRNG_PIC_NO = T2.ENFSN_NO AND T1.PIC_INST_NO = T3.INST_NO AND T1.CASE_MNG_NO = #{CASE_MNG_NO} AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
AND T1.AFTFCT_TRMN_SRNG_TKCG_YN = #{AFTFCT_TRMN_SRNG_TKCG_YN}
AND T1.REASSE_SRNG_TKCG_YN = #{REASSE_SRNG_TKCG_YN}
ORDER BY T1.CASE_MNG_NO, T1.CASE_MNG_NO, T1.SRNG_PIC_NO DESC

mapper.delete:
DELETE /* isry.itgcm.casemng.caseunity.CaseAftfctMapper.deleteCaseReasseSrngDetail(재사정심사자삭제) */
  FROM SEC130 T1  /* 재사정심사자 */
 WHERE T1.CASE_MNG_NO    = #{CASE_MNG_NO}
   AND T1.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
   AND T1.SRNG_PIC_NO    = #{SRNG_PIC_NO}

